import java.io.*;
import java.util.*;

public class Main {
    static class Edge {
        int to;
        int id;
        int weight;

        Edge(int to, int id, int weight) {
            this.to = to;
            this.id = id;
            this.weight = weight;
        }
    }

    static class Cycle {
        long length;
        int[] vertices;

        Cycle(long length, int[] vertices) {
            this.length = length;
            this.vertices = vertices;
        }
    }

    static class State implements Comparable<State> {
        int vertex;
        long distance;

        State(int vertex, long distance) {
            this.vertex = vertex;
            this.distance = distance;
        }

        public int compareTo(State other) {
            return Long.compare(distance, other.distance);
        }
    }

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int e = fs.nextInt();
        int r = fs.nextInt();

        ArrayList<Edge>[] graph = new ArrayList[e];
        for (int i = 0; i < e; i++) graph[i] = new ArrayList<>();

        for (int id = 0; id < r; id++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            int c = fs.nextInt();
            graph[a].add(new Edge(b, id, c));
            graph[b].add(new Edge(a, id, c));
        }

        // Find each cycle using DFS back edges.
        boolean[] visited = new boolean[e];
        int[] parent = new int[e];
        int[] parentEdge = new int[e];
        int[] parentWeight = new int[e];
        int[] depth = new int[e];
        int[] nextEdge = new int[e];
        Arrays.fill(parent, -1);
        Arrays.fill(parentEdge, -1);

        ArrayList<Cycle> cycles = new ArrayList<>();
        int[] stack = new int[e];

        for (int root = 0; root < e; root++) {
            if (visited[root]) continue;

            int top = 0;
            stack[0] = root;
            visited[root] = true;

            while (top >= 0) {
                int u = stack[top];

                if (nextEdge[u] == graph[u].size()) {
                    top--;
                    continue;
                }

                Edge edge = graph[u].get(nextEdge[u]++);
                int v = edge.to;

                if (edge.id == parentEdge[u]) continue;

                if (!visited[v]) {
                    visited[v] = true;
                    parent[v] = u;
                    parentEdge[v] = edge.id;
                    parentWeight[v] = edge.weight;
                    depth[v] = depth[u] + 1;
                    stack[++top] = v;
                } else if (depth[v] < depth[u]) {
                    // This edge connects u to an ancestor v and closes a cycle.
                    long length = edge.weight;
                    ArrayList<Integer> vertices = new ArrayList<>();
                    int current = u;
                    vertices.add(current);

                    while (current != v) {
                        length += parentWeight[current];
                        current = parent[current];
                        vertices.add(current);
                    }

                    int[] cycleVertices = new int[vertices.size()];
                    for (int i = 0; i < vertices.size(); i++) {
                        cycleVertices[i] = vertices.get(i);
                    }
                    cycles.add(new Cycle(length, cycleVertices));
                }
            }
        }

        int k = fs.nextInt();
        StringBuilder answer = new StringBuilder();

        for (int query = 0; query < k; query++) {
            int start = fs.nextInt() - 1;
            long trainLength = fs.nextInt();

            long[] dist = new long[e];
            Arrays.fill(dist, Long.MAX_VALUE / 4);
            dist[start] = 0;

            PriorityQueue<State> pq = new PriorityQueue<>();
            pq.add(new State(start, 0));

            while (!pq.isEmpty()) {
                State current = pq.poll();
                if (current.distance != dist[current.vertex]) continue;

                for (Edge edge : graph[current.vertex]) {
                    long newDistance = current.distance + edge.weight;
                    if (newDistance < dist[edge.to]) {
                        dist[edge.to] = newDistance;
                        pq.add(new State(edge.to, newDistance));
                    }
                }
            }

            long best = Long.MAX_VALUE;
            for (Cycle cycle : cycles) {
                if (cycle.length < trainLength) continue;

                long distance = Long.MAX_VALUE;
                for (int vertex : cycle.vertices) {
                    distance = Math.min(distance, dist[vertex]);
                }

                if (distance < Long.MAX_VALUE / 4) {
                    best = Math.min(best, cycle.length + 2 * distance);
                }
            }

            answer.append(best == Long.MAX_VALUE ? -1 : best).append('\n');
        }

        System.out.print(answer);
    }
}
